# frozen_string_literal: true

require "rails_helper"

RSpec.configure do |config|
  # Generated by `bin/rails rswag:specs:swaggerize` and served by rswag-api at /api-docs
  config.openapi_root = Rails.root.join("swagger").to_s
  config.openapi_format = :yaml

  # Responses must match their schema exactly: every property present, no extra ones
  config.openapi_all_properties_required = true
  config.openapi_no_additional_properties = true

  pagination = {
    type: :object,
    properties: {
      page: { type: :integer, example: 1 },
      per_page: { type: :integer, example: 20 },
      pages: { type: :integer, example: 3 },
      count: { type: :integer, example: 45 },
      next_page: { type: :integer, nullable: true, example: 2 },
      prev_page: { type: :integer, nullable: true, example: nil }
    }
  }

  config.openapi_specs = {
    "v1/swagger.yaml" => {
      openapi: "3.0.1",
      info: {
        title: "Movies on Rails API",
        version: "v1",
        description: "Read-only JSON API with the same movies, sorting and actor filter as the web pages. " \
                     "Lists are paginated with `page` and `per_page` (default 20, at most 100)."
      },
      servers: [ { url: "/" } ],
      paths: {},
      components: {
        schemas: {
          movie: {
            type: :object,
            properties: {
              id: { type: :integer },
              title: { type: :string },
              year: { type: :integer },
              director: { type: :string },
              description: { type: :string },
              average_stars: { type: :number, nullable: true, description: "Average of the reviews' stars (0–5), null without reviews" },
              reviews_count: { type: :integer },
              actors: {
                type: :array,
                items: { type: :object, properties: { id: { type: :integer }, name: { type: :string } } }
              },
              filming_locations: {
                type: :array,
                items: {
                  type: :object,
                  properties: {
                    id: { type: :integer },
                    name: { type: :string },
                    country: { type: :string, description: "ISO 3166-1 alpha-2 code" }
                  }
                }
              },
              url: { type: :string, format: :uri }
            }
          },
          pagination:,
          error: {
            type: :object,
            properties: {
              error: {
                type: :object,
                properties: {
                  code: { type: :string, enum: %w[not_found invalid_parameter] },
                  message: { type: :string }
                }
              }
            }
          }
        }
      }
    }
  }
end
